class PaginationContractTest(unittest.TestCase):
    def test_partial_last_page(self):
        page = paginate(list(range(25)), page=3, per_page=10)
        self.assertEqual(page.pages, 3)
        self.assertEqual(page.items, [20, 21, 22, 23, 24])

    def test_page_past_the_end(self):
        page = paginate(list(range(5)), page=4, per_page=2)
        self.assertEqual(page.items, [])
        self.assertEqual(page.total, 5)

    def test_per_page_clamped_to_max(self):
        page = paginate(list(range(300)), page=1, per_page=1000)
        self.assertEqual(page.per_page, config.MAX_PAGE_SIZE)
        self.assertEqual(len(page.items), config.MAX_PAGE_SIZE)

    def test_per_page_clamped_to_one(self):
        for value in (0, -5):
            page = paginate(list(range(3)), page=1, per_page=value)
            self.assertEqual(page.per_page, 1)
            self.assertEqual(page.items, [0])


